  let K := z.1.1.1
  let xs := z.1.1.2
  let i := z.1.2
  if i<xs.length then
    if z.2 then
      if xs.getD i 0+1<K then some (listExchange (xs,(i,xs.length))) else none
    else
      if 0<xs.getD i 0 then some (listExchange (xs,(xs.length,i))) else none
  else none

