def Selected {m n : ℕ} (A : Instance (Fin m) (Fin n)) (tree : Bool) (a : Fin m×Fin n) : Prop :=
  if tree then A.T.Adj (.inl a.1) (.inr a.2)
  else A.small a.1 a.2=false ∧ ¬A.T.Adj (.inl a.1) (.inr a.2)

